    onUserProfileUpdated: () => userPanel.onUserChanged?.({ reason: 'save', bindingChanged: false, affectsActiveCharacter: false }),
    saveWorldInfo: (id, data, options) => window.appBridge.saveWorldInfo?.(id, data, options),
