  const STICKER_PACK_ASSET_SESSION = 'sticker_pack_assets';
  const STICKER_ICON_SESSION = 'sticker_pack_icons';
  const STICKER_AI_ASSET_SESSION = 'sticker_ai_assets';
  const STICKER_EXPORT_SESSION = 'sticker_export';
