  const buildDocumentPromptText = attachment => {
    const fileMarker = getLocalizedPromptText('attachment.file_marker', '文件');
    const name = String(attachment?.name || fileMarker).trim() || fileMarker;
    const meta = [];
    if (attachment?.mime) meta.push(String(attachment.mime));
    if (attachment?.sizeLabel) meta.push(String(attachment.sizeLabel));
    const header = meta.length ? `【${fileMarker}】${name} (${meta.join(', ')})` : `【${fileMarker}】${name}`;
    const body = String(attachment?.text || '').trim();
    if (!body) return `${header}\n${getLocalizedPromptText('attachment.unreadable', '[无法读取文件内容，仅提供文件信息]')}`;
    const suffix = attachment?.textTruncated
      ? `\n${getLocalizedPromptText('attachment.truncated', '[内容已截断]')}`
      : '';
    return `${header}\n${body}${suffix}`;
  };
  const stripComposerAttachmentPlaceholders = (text = '', attachments = composerAttachments) => {
    let next = String(text || '');
    const list = Array.isArray(attachments) ? attachments : [];
    list.forEach((attachment) => {
      const token = String(attachment?.placeholder || '').trim();
      if (!token) return;
      next = removeTextTokenOnce(next, token);
    });
    return next.trim();
  };
  const buildAttachmentParts = attachments => {
    const parts = [];
    (attachments || []).forEach(attachment => {
      if (!attachment || typeof attachment !== 'object') return;
      if (attachment.kind === 'image' && attachment.url) {
        const url = String(attachment.llmUrl || attachment.url || '').trim();
        if (url) parts.push({ type: 'image_url', image_url: { url } });
        return;
      }
      if (attachment.kind === 'document') {
        const text = buildDocumentPromptText(attachment);
        if (text) parts.push({ type: 'text', text });
      }
    });
    return parts;
  };
  const buildAttachmentMessages = (attachments, { name, avatar } = {}) => {
    const list = [];
    (attachments || []).forEach(attachment => {
	      if (!attachment || typeof attachment !== 'object') return;
	      if (attachment.kind === 'image' && attachment.url) {
	        const isPersistentAsset = attachment.source === 'writing-asset' || attachment.source === 'generated-image';
	        const expiresAt = isPersistentAsset ? 0 : Date.now() + ATTACHMENT_TTL_MS;
        list.push({
          role: 'user',
          type: 'image',
          content: attachment.url,
          name: name || '我',
          avatar,
          time: formatNowTime(),
          meta: {
            attachmentId: attachment.id || '',
            originalName: attachment.name || '',
            expiresAt,
            source: attachment.source || '',
            prompt: attachment.prompt || '',
            placeholder: attachment.placeholder || '',
            localPath: attachment.localPath || '',
            localBytes: Number(attachment.localBytes || 0) || undefined,
            generatedAssetId: attachment.generatedAssetId || '',
          },
        });
        return;
      }
      if (attachment.kind === 'document') {
        list.push({
          role: 'user',
          type: 'document',
          content: attachment.name || '文件',
          name: name || '我',
          avatar,
          time: formatNowTime(),
          meta: {
            attachmentId: attachment.id || '',
            mime: attachment.mime || '',
            size: Number(attachment.size || 0),
            sizeLabel: attachment.sizeLabel || '',
            textTruncated: Boolean(attachment.textTruncated),
            localPath: attachment.localPath || '',
            localBytes: Number(attachment.localBytes || 0) || 0,
            originalName: attachment.originalName || attachment.name || '',
          },
        });
      }
    });
    return list;
  };
  const buildPendingMessagesFromComposer = (attachments, {
    text = '',
    stickerKey = '',
    fallbackContent = '[附件]',
    avatar = '',
    userName = '我',
    time = '',
    replyTarget = null,
  } = {}) => {
    const groupId = `pending-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`;
    const messages = [];
    const cleanText = String(text || '').trim();
    if (cleanText || stickerKey || !attachments?.length) {
      const pendingText = createPendingUserMessage({
        text: cleanText,
        stickerKey,
        fallbackContent,
        avatar,
        userName,
        time,
        replyTarget,
        attachmentsOnly: !cleanText && Boolean(attachments?.length) && !stickerKey,
      });
      pendingText.meta = {
        ...(pendingText.meta || {}),
        pendingGroupId: groupId,
        pendingGroupStatus: 'pending',
      };
      messages.push(pendingText);
    }
    const attachmentMessages = buildAttachmentMessages(attachments || [], { name: userName, avatar })
      .map((message, index) => ({
        ...message,
        status: 'pending',
        meta: {
          ...(message.meta || {}),
          pendingGroupId: groupId,
          pendingGroupStatus: 'pending',
          replyTo: !messages.length && index === 0 && replyTarget ? replyTarget : message.meta?.replyTo,
        },
      }));
    messages.push(...attachmentMessages);
    return messages;
  };
  const persistImageAttachmentMessage = async (message, attachment, sessionId) => {
    if (!message || !attachment) return;
    const dataUrl = String(attachment.url || '').trim();
    if (!dataUrl.startsWith('data:image/')) return;
    try {
      const resp = await safeInvoke('save_attachment', {
        sessionId,
        dataUrl,
        fileName: attachment.name || '',
      });
      const path = String(resp?.path || '').trim();
      if (!path) return;
      const nextMeta = {
        ...(message.meta || {}),
        localPath: path,
        localBytes: Number(resp?.bytes || 0) || undefined,
        savedAt: Date.now(),
      };
      const updated = chatStore.updateMessage(message.id, { meta: nextMeta }, sessionId);
      ui.updateMessage(message.id, updated || { ...message, meta: nextMeta });
    } catch (err) {
      logger.warn('save attachment failed', err);
    }
  };
