    const queue = createProtocolDeliveryQueue(items, { ...options, startAfter }, effects);
    if (!sessionId) return queue;
    const trackedQueues = protocolDeliveryQueuesBySession.get(sessionId) || new Set();
    trackedQueues.add(queue);
