	    const oldToken = resolveInlineGeneratedImageTokenForMessage(current, originalAsset, inlineGeneratedImage);
	    if (!oldToken) {
	      window.toastr?.warning?.('没有找到这张插图在正文中的位置');
	      return false;
	    }
	    const mediaSurface = resolveMediaSurfaceForSession(sessionId);
