        getDraft: sid => chatStore.getDraft(sid),
        getMirrorDraft: sid => readDraftMirror(sid),
        setInputText: value => ui.setInputText(value),
        syncReplyTargetComposer,
        setSessionLabel: sid => ui.setSessionLabel(sid),
