        restoreTailMemory: restoreMemoryFromCurrentTailAssistant,
        prefetchRawOriginals: sid => chatStore.prefetchRawOriginals?.(sid),
        setRenderState: (sid, state) => chatRenderState.set(sid, state),
        logger,
